/**
 * @file StoryNarrative.ts
 * @description 퀘스트 나레이션 층 (141차) — 186편 전부에 **주인공 시점 서두 · NPC의 말 · 내용 기반 선택지**를 붙인다.
 *
 * 왜 따로 두나
 *  - `StoryQuestDatabase`의 `descKo`는 설계 요약(무엇을 배우는 편인가)이고, 플레이어가 읽는 글은 이 파일이다.
 *    표는 표대로 두고 이야기는 이야기대로 — 둘을 한 문자열에 섞으면 둘 다 나빠진다(사용자 지시: "나무위키 정의문 금지").
 *  - 선택지 라벨·응답은 퀘스트 내용에서 나온다. 표준 세트("맡겨 주셔서 고맙습니다 / 끝냈습니다")는 폴백일 뿐이다.
 *
 * 쓰는 규칙
 *  - `intro` = 1인칭 현재형. 누가·어디서·왜·무엇을 하려는지가 문장 안에 있다. 감각과 판단으로 쓰고 정의하지 않는다.
 *  - `offer`/`progress`/`done` = 발주 NPC의 **말**만(따옴표 없음). 화자는 대화창이 초상으로 보여 준다.
 *  - `complete` = 완료 선택지. **보상은 미리 보이지 않는다** — 응답(`reply`)이 보상을 자연스럽게 드러내고,
 *    고르지 않은 답은 `???`로 남는다(재도전 동기). `payMult`는 표준 품삯 배율(`choicesFor`가 환산).
 *  - `offerChoices` = 발주 선택지. `once`/`event` 정책 퀘는 `decline: true` 답이 반드시 하나 있다.
 *  - **영문은 짝 파일 `StoryNarrativeEn.ts`에 둔다**(151차). 여기서 합쳐 `introEn`·`offerEn`… 으로 얹고,
 *    클라이언트 i18n 사전이 `allNarrativeLines()`로 ko→en 쌍을 받아 간다(원문이 곧 키).
 *    선택지(`complete`/`offerChoices`) 영문은 아직 없다 — `labelEn = labelKo` 폴백이 유지된다.
 */

import type { ChoiceOutcome, ChoiceRequires, QuestChoiceDef, QuestNarrative } from '../types/Story.js';
import { STORY_NARRATIVE_EN } from './StoryNarrativeEn.js';

// ── 헬퍼 ──
type C = QuestChoiceDef;
const c = (id: string, label: string, reply: string, outcome: ChoiceOutcome = {}, requires?: ChoiceRequires): C =>
  ({ id, labelKo: label, labelEn: label, replyKo: reply, replyEn: reply, outcome, requires });
/** 발주 거절 답 — once/event 정책의 필수 항목 */
const no = (label: string, reply: string, affinity = -0.03): C => c('decline', label, reply, { decline: true, affinity });

export interface NarrativeEntry extends QuestNarrative {
  complete?: C[];
  offerChoices?: C[];
}
interface NpcLines { offer?: string; progress?: string; done?: string; obj?: string[]; epi?: string }
const N = (intro: string, npc: NpcLines = {}, complete?: C[], offerChoices?: C[]): NarrativeEntry =>
  ({ intro, offer: npc.offer, progress: npc.progress, done: npc.done, objectives: npc.obj, epilogue: npc.epi, complete, offerChoices });

